301	export function parseCommand(line: string): SidecarCommand {
302	  let raw: unknown;
303	  try {
304	    raw = JSON.parse(line);
305	  } catch {
306	    throw new ProtocolError("line is not valid JSON");
307	  }
308	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new ProtocolError("message must be a JSON object");
309	  const msg = raw as Record<string, unknown>;
310	  const id = typeof msg.id === "string" && msg.id ? msg.id : undefined;
311	  const version = msg.v;
312	  if (typeof version !== "number" || !Number.isInteger(version) || version < PROTOCOL_MIN || version > PROTOCOL_MAX) {
313	    throw new ProtocolError(`unsupported protocol version: ${String(msg.v)}`, id);
314	  }
315	  const requireId = (type: string): string => {
316	    if (!id) throw new ProtocolError(`${type} requires id`);
317	    return id;
318	  };
319	  switch (msg.type) {
320	    case "initialize": {
321	      const requestId = requireId("initialize");
322	      const client = msg.client;
323	      if (!client || typeof client !== "object" || Array.isArray(client)) throw new ProtocolError("initialize requires client: { name, version }", requestId);
324	      const { name, version: clientVersion } = client as Record<string, unknown>;
325	      for (const [field, value] of [["name", name], ["version", clientVersion]] as const) {
326	        if (typeof value !== "string" || !value.trim()) throw new ProtocolError(`initialize requires client.${field}: a non-empty string`, requestId);
327	        if (value.length > MAX_CLIENT_FIELD) throw new ProtocolError(`initialize client.${field} is longer than ${MAX_CLIENT_FIELD} characters`, requestId);
328	      }
329	      const bound = (field: "protocol_min" | "protocol_max"): number | undefined => {
330	        const value = msg[field];
331	        if (value === undefined) return undefined;
332	        if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > MAX_PROTOCOL_NUMBER) {
333	          throw new ProtocolError(`initialize ${field} must be an integer from 1 to ${MAX_PROTOCOL_NUMBER}`, requestId);
334	        }
335	        return value;
336	      };
337	      const min = bound("protocol_min");
338	      const max = bound("protocol_max");
339	      if ((min === undefined) !== (max === undefined)) throw new ProtocolError("initialize requires protocol_min and protocol_max together", requestId);
340	      if (min !== undefined && max !== undefined && min > max) throw new ProtocolError(`initialize protocol_min (${min}) is greater than protocol_max (${max})`, requestId);
341	      if (msg.experimental !== undefined && typeof msg.experimental !== "boolean") throw new ProtocolError("initialize experimental must be a boolean", requestId);
342	      // A client that names no range speaks the version it wrote this message in.
343	      return {
344	        type: "initialize", id: requestId, client: { name: name as string, version: clientVersion as string },
345	        protocol_min: min ?? version, protocol_max: max ?? version, experimental: msg.experimental === true,
346	      };
347	    }
348	    case "prompt.submit": {
349	      const requestId = requireId("prompt.submit");
350	      const text = msg.text;
351	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("prompt.submit requires non-empty text", requestId);
352	      return { type: "prompt.submit", id: requestId, text };
353	    }
354	    case "steer": {
355	      const requestId = requireId("steer");
356	      const text = msg.text;
357	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("steer requires non-empty text", requestId);
358	      return { type: "steer", id: requestId, text };
359	    }
360	    case "cancel":
361	      return { type: "cancel" };
362	    case "approve":
363	      return { type: "approve", id: requireId("approve"), always: msg.always === true };
364	    case "deny":
365	      return { type: "deny", id: requireId("deny") };
366	    case "answer": {
367	      const requestId = requireId("answer");
368	      if (typeof msg.question !== "string" || !/^[0-9a-f]{12}$/.test(msg.question)) throw new ProtocolError("answer requires question: the 12-character needsInput.id", requestId);
369	      if (msg.option !== "approve" && msg.option !== "decline") throw new ProtocolError("answer requires option: approve or decline", requestId);
370	      return { type: "answer", id: requestId, question: msg.question, option: msg.option };
371	    }
372	    case "checkpoint.choice": {
373	      const requestId = requireId("checkpoint.choice");
374	      const choices = ["read_only", "without_checkpoint", "retry", "allow_sensitive", "cancel", "other"] as const;
375	      if (!choices.includes(msg.choice as typeof choices[number])) throw new ProtocolError("checkpoint.choice requires a supported choice", requestId);
376	      return { type: "checkpoint.choice", id: requestId, choice: msg.choice as typeof choices[number] };
377	    }
378	    case "slash": {
379	      const requestId = requireId("slash");
380	      const command = msg.command;
381	      if (typeof command !== "string" || !command.trim()) throw new ProtocolError("slash requires command", requestId);
382	      return { type: "slash", id: requestId, command, args: typeof msg.args === "string" ? msg.args : "" };
383	    }
384	    case "tool.detail": {
385	      const requestId = requireId("tool.detail");
386	      const evidence = msg.evidence;
387	      if (typeof evidence !== "string" || !evidence) throw new ProtocolError("tool.detail requires evidence", requestId);
388	      return { type: "tool.detail", id: requestId, evidence };
389	    }
390	    case "receipt":
391	      return { type: "receipt", id: requireId("receipt") };
392	    case "models.list":
393	      return { type: "models.list", id: requireId("models.list") };
394	    case "model.select": {
395	      const requestId = requireId("model.select");
396	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.model !== "string" || !msg.model.trim()) {
397	        throw new ProtocolError("model.select requires provider and model", requestId);
398	      }
399	      return { type: "model.select", id: requestId, provider: msg.provider, model: msg.model };
400	    }
401	    case "provider.connect": {
402	      const requestId = requireId("provider.connect");
403	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.method !== "string" || !msg.method) {
404	        throw new ProtocolError("provider.connect requires provider and method", requestId);
405	      }
406	      if (msg.key !== undefined && typeof msg.key !== "string") throw new ProtocolError("provider.connect key must be a string", requestId);
407	      if (msg.endpoint !== undefined && (typeof msg.endpoint !== "string" || !msg.endpoint || msg.endpoint.length > 2048 || /[\r\n\0]/.test(msg.endpoint))) {
408	        throw new ProtocolError("provider.connect endpoint must be a valid single-line URL", requestId);
409	      }
410	      return {
411	        type: "provider.connect", id: requestId, provider: msg.provider, method: msg.method,
412	        ...(typeof msg.key === "string" ? { key: msg.key } : {}),
413	        ...(typeof msg.endpoint === "string" ? { endpoint: msg.endpoint } : {}),
414	      };
415	    }
416	    case "provider.cancel":
417	      return { type: "provider.cancel", id: requireId("provider.cancel") };
418	    case "provider.local-cancel":
419	      return { type: "provider.local-cancel", id: requireId("provider.local-cancel") };
420	    case "provider.disconnect": {
421	      const requestId = requireId("provider.disconnect");
422	      if (typeof msg.provider !== "string" || !msg.provider) throw new ProtocolError("provider.disconnect requires provider", requestId);
423	      return { type: "provider.disconnect", id: requestId, provider: msg.provider };
424	    }
425	    case "shutdown":
426	      return { type: "shutdown" };
427	    default:
428	      throw new ProtocolError(`unknown message type: ${String(msg.type)}`, id);
429	  }
430	}
