437	/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
438	const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;
439	
440	export function stripEscapes(text: string): string {
441	  return text.replace(TERMINAL_ESCAPE, "");
442	}
