449	/** Operator-supplied text as shown to an operator or written to a record: escapes and control characters gone, secrets redacted, one line, capped. */
450	export function safeOperatorText(text: string, max = 300): string {
451	  return redactSecrets(stripEscapes(String(text)).replace(/[\x00-\x1f\x7f-\x9f]+/g, " ")).replace(/\s+/g, " ").trim().slice(0, max);
452	}
