454	export function toolSubject(args: Record<string, any>, tool?: string): string {
455	  if (tool === "steering_conflict" && Array.isArray(args.negates)) {
456	    const ids = args.negates.map((n: any) => safeOperatorText(String(n?.id ?? ""), 12)).join(", ");
457	    return safeOperatorText(`steering ${args.steering} negates ${ids}: ${args.text}`, 200);
458	  }
459	  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
460	  return redactPlain(String(subject)).replace(/\s+/g, " ").trim().slice(0, 200);
461	}
