512	/** What went wrong, in words an operator can act on. */
513	function providerProblemWords(record: ProviderRecoveryRecord): string {
514	  const last = record.submissions[record.submissions.length - 1];
515	  const status = last?.httpStatus;
516	  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
517	  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
518	  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
519	  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
520	  if (record.condition === "DRAINING") return "the provider is restarting";
521	  if (last?.kind === "timeout") return "the provider did not answer in time";
522	  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
523	  return "the provider returned an error";
524	}
