544	 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
545	 */
546	export function providerRecoveryStatus(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): StatusNotice | undefined {
547	  if (record.state === "PROBING") return undefined;
548	  const detail = rawProviderCause(record);
549	  const where = record.endpoint ? ` at ${persistableEndpoint(record.endpoint)}` : "";
550	  const problem = providerProblemWords(record);
551	  switch (record.state) {
552	    case "WAITING": {
553	      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
554	      const left = minutesWords(Math.max(0, record.policy.deadlineMs - record.waitedMs));
555	      const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
556	      const text = `Waiting for the model provider${where}: ${problem}. Retry ${record.submissions.length}, next attempt in ${secs}s; gives up in ${left}. Your work is kept. /details shows the raw error; esc cancels.${discarded}`;
557	      return { text: redactSecrets(text), key: PROVIDER_STATUS_KEY, detail };
558	    }
559	    case "RESUMED":
560	      return { text: `The model provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`, key: PROVIDER_STATUS_KEY, detail: `Recovered; the earlier error was:\n${detail}` };
561	    case "CANCELLED":
562	      return { text: "Stopped waiting for the model provider.", key: PROVIDER_STATUS_KEY, detail };
563	    default:
564	      return {
565	        text: redactSecrets(`Nexus stopped retrying the model provider${where}: ${problem}. Check the connection or use /connect, then send your message again. /details shows the raw error.`),
566	        key: PROVIDER_STATUS_KEY,
567	        detail,
568	      };
569	  }
570	}
