603	/** Lines of a command's output carried in `tool.end` for the transcript preview. */
604	export const TOOL_PREVIEW_LINES = 8;
605	
606	export interface ToolSummary {
607	  summary: string;
608	  lines: number;
609	  preview?: string;
610	  exit_code?: number | null;
611	  duration_ms?: number;
612	  timed_out?: boolean;
613	}
614	
615	/**
616	 * What the transcript shows for a finished tool. A command's JSON result (`stdout`, `stderr`, `exit_code`) becomes a
617	 * real summary (`exit 0 · 122 lines`, or `no output`), the count of its output lines and a bounded preview of them;
618	 * other tools keep the first line of their output (or error) as the summary.
619	 */
620	export function toolSummary(success: boolean, output: string, error?: string): ToolSummary {
621	  const command = commandResult(output);
622	  if (command) {
623	    const body = [command.stdout.trimEnd(), command.stderr.trimEnd()].filter(Boolean).join("\n");
624	    const rows = body ? body.split(/\r?\n/) : [];
625	    const exit = command.timed_out ? "timed out" : command.exit_code === null ? "no exit code" : `exit ${command.exit_code}`;
626	    const failure = success ? "" : (error ?? "").split(/\r?\n/).find((line) => line.trim())?.trim() ?? "";
627	    const summary = failure && !failure.startsWith("{") ? failure : `${exit} · ${rows.length ? `${rows.length} line${rows.length === 1 ? "" : "s"}` : "no output"}`;
628	    return {
629	      summary: redactPlain(summary).replace(/\s+/g, " ").slice(0, MAX_SUMMARY),
630	      lines: rows.length,
631	      preview: (rows.length > TOOL_PREVIEW_LINES ? rows.slice(-TOOL_PREVIEW_LINES) : rows).map((row) => safeTerminal(row).slice(0, 400)).join("\n"),
632	      exit_code: command.exit_code,
633	      ...(command.duration_ms !== undefined ? { duration_ms: command.duration_ms } : {}),
634	      ...(command.timed_out ? { timed_out: true } : {}),
635	    };
636	  }
637	  const text = redactPlain(success ? output || "" : error || output || "").trim();
638	  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
639	  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
640	}
641	
642	/** The structured result of a shell command tool, when `output` is one. */
643	function commandResult(output: string): { stdout: string; stderr: string; exit_code: number | null; duration_ms?: number; timed_out?: boolean } | undefined {
644	  if (!output || output.trimStart()[0] !== "{") return undefined;
645	  try {
646	    const parsed = JSON.parse(output);
647	    if (parsed && typeof parsed === "object" && typeof parsed.stdout === "string" && "exit_code" in parsed) {
648	      return {
649	        stdout: parsed.stdout,
650	        stderr: typeof parsed.stderr === "string" ? parsed.stderr : "",
651	        exit_code: typeof parsed.exit_code === "number" ? parsed.exit_code : null,
652	        ...(typeof parsed.duration_ms === "number" ? { duration_ms: parsed.duration_ms } : {}),
653	        ...(parsed.timed_out === true ? { timed_out: true } : {}),
654	      };
655	    }
656	  } catch {}
657	  return undefined;
658	}
