296	  /**
297	   * Negotiation for this connection. It only records connection state, so it is answered at any time, a running turn
298	   * included. Rule: a connection negotiates once. After an `initialized` answer every later `initialize` is refused
299	   * with BAD_REQUEST, because a version or an experimental set that changed mid-connection would leave both sides
300	   * unsure which rules a message in flight was written under. An `initialize` refused with UNSUPPORTED_PROTOCOL
301	   * settled nothing, so the client may send another; the sidecar keeps serving either way.
302	   */
303	  private initialize(id: string, clientMin: number, clientMax: number, experimental: boolean): void {
304	    if (this.negotiated) {
305	      this.emit({ type: "error", id, code: "BAD_REQUEST", message: `initialize was already answered on this connection (protocol ${this.negotiated.protocol}); a connection negotiates once.` });
306	      return;
307	    }
308	    const protocol = Math.min(clientMax, PROTOCOL_MAX);
309	    if (protocol < Math.max(clientMin, PROTOCOL_MIN)) {
310	      this.unsupportedProtocol = `No common protocol version: the client speaks ${clientMin} to ${clientMax}, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`;
311	      this.emit({
312	        type: "error", id, code: "UNSUPPORTED_PROTOCOL",
313	        message: this.unsupportedProtocol,
314	      });
315	      return;
316	    }
317	    this.negotiated = { protocol, experimental: experimental ? this.experimentalOffered : [] };
318	    this.unsupportedProtocol = undefined;
319	    this.emit({ type: "initialized", id, protocol, capabilities: [...SIDECAR_CAPABILITIES], experimental: [...this.negotiated.experimental] });
320	  }
321	
322	  /**
323	   * The gate every experimental feature's handler calls first: true when this connection enabled `name` (it sent
324	   * `initialize` with `experimental: true` and this sidecar offers `name`). Otherwise it answers `id` with
325	   * EXPERIMENTAL_DISABLED and returns false, and the handler does nothing.
326	   */
327	  requireExperimental(name: string, id?: string): boolean {
328	    if (this.negotiated?.experimental.includes(name)) return true;
329	    const message = this.experimentalOffered.includes(name)
330	      ? `${name} is experimental: send initialize with experimental: true before using it.`
331	      : `${name} is not an experimental feature this sidecar offers.`;
332	    this.emit({ type: "error", ...(id ? { id } : {}), code: "EXPERIMENTAL_DISABLED", message });
333	    return false;
334	  }
