366	  private async providerConnect(id: string, provider: string, method: string, key?: string, endpoint?: string): Promise<void> {
367	    const result = (success: boolean, message: string) =>
368	      this.emit({ type: "provider.result", id, provider: provider, success, message: message });
369	    try {
370	      if (provider === "appliance" && method === "local-endpoint") {
371	        if (!endpoint) {
372	          result(false, "An endpoint URL is required.");
373	          return;
374	        }
375	        const prepared = await prepareLocalEndpoint(this.app.getConfig(), endpoint, key ?? "", id);
376	        if (!prepared.cancelled) result(prepared.ok, prepared.message);
377	        return;
378	      }
379	      if (method === "api-key") {
380	        const r = await connectWithKey(this.app.getConfig(), provider, key ?? "");
381	        result(r.ok, r.message);
382	        return;
383	      }
384	      if (endpoint !== undefined) {
385	        result(false, "Endpoint URLs are only accepted for local endpoint setup.");
386	        return;
387	      }
388	      const signIn = await startSignIn(this.app.getConfig(), provider, method);
389	      this.signIns.set(id, signIn);
390	      this.emit({
391	        type: "provider.auth",
392	        id,
393	        provider,
394	        url: signIn.prompt.url,
395	        ...(signIn.prompt.userCode ? { user_code: signIn.prompt.userCode } : {}),
396	        instructions: signIn.prompt.instructions,
397	      });
398	      const r = await signIn.done;
399	      this.signIns.delete(id);
400	      result(r.ok, r.message);
401	    } catch (err) {
402	      this.signIns.delete(id);
403	      result(false, String((err as Error).message ?? err));
404	    }
