509	  /** Reports BUSY for `id` when a turn or command is running or the sidecar is shutting down. */
510	  private rejectBusy(id: string): boolean {
511	    if (!this.shutdownPromise && !this.activeTurn) return false;
512	    const message = this.shutdownPromise ? "The sidecar is shutting down." : "A turn or command is running; cancel it or wait for its result.";
513	    this.emit({ type: "error", id, code: "BUSY", message });
514	    return true;
515	  }
