517	  /**
518	   * /compact while a turn or command runs. During an agent turn the agent holds it until the turn's next step boundary
519	   * (after the in-flight inference and its tool batch, approvals included, have settled) or the turn's end. While another
520	   * command runs, it waits here and runs as its own job afterwards. Each request is acknowledged now (notice) and gets

520	   * command runs, it waits here and runs as its own job afterwards. Each request is acknowledged now (notice) and gets
521	   * its outcome later (slash.result for its id). A duplicate shares the queued request's outcome; at most one request
522	   * per kind (default, --llm) waits; cancellation and shutdown end waiting requests with that outcome.
523	   */
524	  private queueCompaction(id: string, llm: boolean): void {
525	    const queued = this.app.getAgent().requestCompaction(id, llm);
526	    if (queued.status !== "no_active_turn") {
527	      this.emit({ type: "notice", text: queued.message });
528	      return;
529	    }
530	    const existing = this.pendingCompactions.find((p) => p.llm === llm);
531	    if (existing) {
532	      existing.ids.push(id);
533	      this.emit({ type: "notice", text: `A /compact${llm ? " --llm" : ""} is already waiting; this request shares its outcome.` });
534	      return;
535	    }
536	    this.pendingCompactions.push({ ids: [id], llm });
537	    this.emit({ type: "notice", text: `/compact${llm ? " --llm" : ""} queued: it runs when the current command finishes.` });
538	  }
539	
540	  private compactionResult(ids: string[], ok: boolean, message: string): void {
541	    for (const id of ids) this.emit({ type: "slash.result", id, command: "compact", success: ok, output: message });
542	  }
543	
544	  /** Ends waiting /compact requests that will not run. */
545	  private dropPendingCompactions(reason: string): void {
546	    for (const p of this.pendingCompactions) this.compactionResult(p.ids, false, `/compact was not run: ${reason}.`);
547	    this.pendingCompactions = [];
548	  }
