601	  /**
602	   * The one way a prompt, a steer that starts a turn and a follow-up start a turn. When start-up found nothing answering,
603	   * it waits for that probe, asks again (the operator may have connected a provider or started a server since) and
604	   * refuses with the reason rather than entering a retry loop. A cancelled probe says nothing about the provider: the
605	   * gate stays and the turn does not run.
606	   */
607	  private async gatedTurn(
608	    id: string,
609	    text: string | any[],
610	    signal: AbortSignal,
611	    hooks: { admitted?: () => void; refused: (message: string) => void },
612	    turnArgs?: { title?: string; checkpoint?: string; step?: boolean },
613	  ): Promise<void> {
614	    // Cancelled while the gate was checking: the message is reported back (never silently dropped), not run.
615	    const cancelled = "Cancelled before it was sent.";
616	    await this.startupProbe;
617	    // With no known problem a cancel is the turn's own business (it reports INTERRUPTED); only the gate reports it here.
618	    if (this.providerProblem) {
619	      const problem = await this.app.getAgent().probeEndpointProblem(signal);
620	      if (signal.aborted) return hooks.refused(cancelled);
621	      this.providerProblem = problem?.blocking ? problem : undefined;
622	      if (this.providerProblem) {
623	        hooks.refused(noProviderRefusal(this.providerProblem));
624	        return;
625	      }
626	    }
627	    hooks.admitted?.();
628	    await this.turn(id, text, turnArgs?.title ?? String(text), turnArgs?.checkpoint ?? `Turn: ${String(text).slice(0, 30)}`, signal, turnArgs?.step);
629	  }
