631	  private observerFor(turnId: string): AgentObserver {
632	    const open = new Map<number, string>();
633	    // The evidence ledger is a sink of its own, so its copy of the tool name is sanitized before it is stored; the events carry the raw name.
634	    return {
635	      onAssistantDelta: (delta) => this.emit({ type: "assistant.delta", turn_id: turnId, text: delta }),
636	      onToolStart: ({ dispatch, callId, tool: rawTool, args }) => {
637	        const tool = rawTool;
638	        const subject = toolSubject(args, rawTool);
639	        const evidence = this.evidence.start(turnId, redactThenCap(rawTool, 200), subject, args);
640	        open.set(dispatch, evidence);
641	        this.emit({ type: "tool.start", turn_id: turnId, call_id: callId, tool, subject, evidence });
642	      },
643	      onToolEnd: ({ dispatch, callId, tool: rawTool, success, output, error, denied }) => {
644	        const tool = rawTool;
645	        const evidence = open.get(dispatch) ?? "";
646	        open.delete(dispatch);
647	        const declined = denied === true && this.operatorDeclined;
648	        if (denied === true) this.operatorDeclined = false;
649	        this.evidence.end(evidence, success, output, error, declined);
650	        // A denial is the operator's own decision: say so in a sentence, not the model-facing text.
651	        const summary: ToolSummary = declined ? { summary: DENIED_BY_OPERATOR, lines: 1 } : toolSummary(success, output, error);
652	        this.emit({
653	          type: "tool.end", turn_id: turnId, call_id: callId, tool, success, evidence,
654	          ...summary,
655	          ...(declined ? { denied: true as const } : {}),
656	        });
657	      },
658	      onProviderRecovery: ({ record, discardedPartialOutput }) => {
659	        const status = providerRecoveryStatus(record, discardedPartialOutput);
660	        if (status) this.emit({ type: "notice", ...status });
661	      },
662	      onStreamStall: ({ stalled, silentSecs }) =>
663	        this.emit({ type: "stream.stall", turn_id: turnId, stalled, silent_secs: silentSecs }),
664	      onActivity: ({ phase, step, segment, tool, subject }) =>
665	        this.emit({
666	          type: "activity",
667	          turn_id: turnId,
668	          phase,
669	          step,
670	          segment,
671	          ...this.budget(),
672	          ...(tool ? { tool: tool } : {}),
673	          ...(subject ? { subject: subject } : {}),
674	        }),
675	      onFileChange: ({ dispatch, callId, path: file, change }) => {
676	        const evidence = open.get(dispatch) ?? "";
677	        const safe = formatSafeSidecarText(change.diff);
678	        const fullPath = this.keepOperationDiff(evidence, callId, safe);
679	        this.evidence.attachDiff(evidence, safe, fullPath);
680	        const { preview, truncated, totalLines } = previewDiff(safe, DIFF_PREVIEW_LINES, DIFF_PREVIEW_CHARS);
681	        this.emit({
682	          type: "file.diff",
683	          turn_id: turnId,
684	          call_id: callId,
685	          evidence,
686	          path: file,
687	          kind: change.kind,
688	          added: change.added,
689	          removed: change.removed,
690	          preview,
691	          truncated,
692	          total_lines: totalLines,
693	          diff_lines: countDiffLines(safe),
694	          hunks: change.hunks ?? 0,
695	          ...(fullPath ? { full_path: fullPath } : {}),
696	          ...(change.note ? { note: change.note } : {}),
697	        });
698	      },
699	      onContinuation: ({ kind, n, max, detail }) => {
700	        const text =
701	          kind === "requirements"
702	            ? `Requirements still open (${redactThenCap(detail, 120)}): Nexus asked the agent to continue (${n} of ${max}).`
703	            : `The agent repeated ${redactThenCap(detail, 200)} with an unchanged result: Nexus told it to change approach (${n} of ${max}).`;
704	        this.emit({ type: "notice", text: text });
705	      },
706	      onNotice: (text) => this.emit({ type: "notice", text: text }),
707	      onCompaction: ({ id, ok, message }) => this.compactionResult([id], ok, message),
708	      onSteering: ({ id, status, step, text, reason }) => {
709	        if (status === "applied") this.steerAck(id, "applied", `Applied at step ${step}.`);
710	        else this.steerAck(id, "cancelled", `Not applied: ${reason ?? "the turn ended first"}. Your message is back in the composer.`, text);
711	      },
712	    };
713	  }
