715	  /** The running turn's budget as the client shows it: total steps (across segments) and the time limit. */
716	  private budget(): { max_steps: number; max_minutes?: number } {
717	    const config = this.app.getConfig();
718	    const continuation = config.continuation;
719	    // Only limits the operator set are shown as limits; an unbounded budget sends none (the client shows "step N").
720	    if (!continuation) return { max_steps: config.maxSteps };
721	    return {
722	      ...(Number.isFinite(continuation.maxTotalSteps) ? { max_steps: continuation.maxTotalSteps } : {}),
723	      ...(Number.isFinite(continuation.maxTurnMinutes) ? { max_minutes: continuation.maxTurnMinutes } : {}),
724	    } as { max_steps: number; max_minutes?: number };
725	  }
