727	  private confirmFor(turnId: string, signal: AbortSignal) {
728	    return (tool: string, args: Record<string, any>, question?: AbortSignal) => {
729	      if (this.alwaysApprove && tool !== DELIBERATE_APPROVAL) return Promise.resolve(true);
730	      return this.requestApproval(turnId, question ? AbortSignal.any([signal, question]) : signal, tool, args);
731	    };
732	  }
