734	  /** One agent turn: checkpoint, run, save the session, report the result. `step`: one cycle of the unfinished objective. */
735	  private async turn(turnId: string, prompt: string | any[], label: string, checkpoint: string, signal: AbortSignal, step = false): Promise<void> {
736	    const agent = this.app.getAgent();
737	    let allowSensitiveCheckpoint = false;
738	    try {
739	      agent.enterNamedWorktreeBeforeTurn(); // the snapshot is of the worktree the turn edits
740	    } catch (err) {
741	      this.emit({ type: "error", id: turnId, code: "INTERNAL", message: formatSafeSidecarText(errorText(err)) });
742	      return;
743	    }
744	    if (this.app.getConfig().readOnly) {
745	      // Read-only turns cannot change the workspace, so a workspace rollback snapshot is unnecessary.
746	      agent.setCheckpointReadOnlyFallback(false);
747	    } else {
748	      let checkpointReady = false;
749	      while (!checkpointReady) {
750	        try {
751	          this.app.getCheckpointManager().createCheckpoint(
752	            checkpoint,
753	            allowSensitiveCheckpoint ? { allowSensitive: true } : undefined,
754	          );
755	          const previousApprovalMode = agent.getApprovalMode();
756	          agent.setCheckpointReadOnlyFallback(false);
757	          if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
758	          checkpointReady = true;
759	        } catch (err) {
760	          const sensitiveContentBlocked = err instanceof SensitivePersistenceError;
761	          const failure = capText(
762	            formatSafeSidecarText(errorText(err))
763	              .replace(/\s+/g, " ")
764	              .trim()
765	              .replace(/;\s*no checkpoint was written\.?$/i, ""),
766	            100,
767	          );
768	          const message = sensitiveContentBlocked
769	            ? undefined
770	            : `Checkpoint failed: ${failure}. No checkpoint was written. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 retry checkpoint normally, 4 cancel this turn, or 5 re-enter the instruction.`;
771	          const choices: readonly CheckpointChoice[] = sensitiveContentBlocked
772	            ? ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"]
773	            : ["read_only", "without_checkpoint", "retry", "cancel", "other"];
774	          const choice = await this.requestCheckpointChoice(turnId, signal, message, choices);
775	          if (choice === "cancel" || choice === "other") {
776	            const message = choice === "other"
777	              ? "This turn was not started. Enter a different instruction in the composer."
778	              : "This turn was cancelled before it started.";
779	            this.emit({ type: "error", id: turnId, code: "INTERNAL", message });
780	            return;
781	          }
782	          if (choice === "read_only") {
783	            agent.setCheckpointReadOnlyFallback(true);
784	            this.emit({ type: "notice", text: "Continuing this turn in read-only mode as requested. Workspace changes, unsafe commands, external actions, and delegation are disabled." });
785	            this.emitSessionState();
786	            checkpointReady = true;
787	          } else if (choice === "without_checkpoint") {
788	            const previousApprovalMode = agent.getApprovalMode();
789	            agent.setCheckpointReadOnlyFallback(false);
790	            if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
791	            this.emit({ type: "notice", text: "Continuing in the current mode without a rollback checkpoint, as requested." });
792	            checkpointReady = true;
793	          } else if (choice === "retry") {
794	            this.emit({ type: "notice", text: "Retrying checkpoint without changing sensitive-persistence settings. The turn remains paused until the retry succeeds or you choose another option." });
795	          } else if (choice === "allow_sensitive") {
796	            allowSensitiveCheckpoint = true;
797	            this.emit({ type: "notice", text: "Retrying checkpoint with sensitive persistence allowed, as requested; this may persist sensitive workspace content. The turn will wait until the retry succeeds or you choose another option." });
798	          }
799	        }
800	      }
801	    }
802	    if (typeof prompt === "string" && !step) {
803	      const decision = agent.objectiveDecision(prompt);
804	      if (decision.kind === "amend") {
805	        this.emit({
806	          type: "notice",
807	          text: `This message continues the unfinished objective (${decision.unresolved} unresolved requirement${decision.unresolved === 1 ? "" : "s"}); its numbered items, if any, are added to it. /requirements clear starts a new objective.`,
808	        });
809	      }
810	    }
811	    agent.setObserver(this.observerFor(turnId));
812	    this.sessionTitle = label;
813	    // Work done so far, and changes still awaiting verification, survive the process ending mid-turn.
814	    agent.setProgressListener(() => this.saveSession(label));
815	    let turn: TurnResult;
816	    try {
817	      turn = await agent.runTurn(prompt, this.confirmFor(turnId, signal), step ? { signal, step: true, resume: true } : { signal });
818	    } catch (err) {
819	      turn = failedTurnFromError(err, this.app.getConfig().maxSteps, agent.hasUnverifiedChanges());
820	    } finally {
821	      agent.setObserver(undefined);
822	      agent.setProgressListener(() => this.saveSession(this.sessionTitle));
823	    }
824	    let saved: boolean;
825	    try {
826	      saved = withDurableSync(() => this.saveSession(label, turn));
827	    } catch (err) {
828	      saved = false;
829	      this.emit({ type: "notice", text: `The session could not be saved: ${errorText(err)}` });
830	    }
831	    const { heading, line } = summarizeTurn(turn);
832	    const projected = projectTurn(turn);
833	    this.lastTurn = { heading, turn: projected };
834	    const summary = turn.execution === "COMPLETED" ? agent.getCompletionSummary() : undefined;
835	    this.emit({
836	      type: "turn.result",
837	      turn_id: turnId,
838	      heading: heading,
839	      line: line,
840	      turn: projected,
841	      model_summary: summary
842	        ? { summary: summary.summary, ...(summary.notes ? { notes: summary.notes } : {}) }
843	        : null,
844	      saved,
845	    });
846	  }
