855	  private openApproval(turnId: string, signal: AbortSignal, tool: string, args: Record<string, any>): Promise<boolean> {
856	    if (tool !== DELIBERATE_APPROVAL) this.operatorDeclined = false;
857	    if (this.alwaysApprove && tool !== DELIBERATE_APPROVAL) return Promise.resolve(true);
858	    if (signal.aborted) return Promise.resolve(false);
859	    const id = `approval-${++this.approvalSeq}`;
860	    return new Promise<boolean>((resolve) => {
861	      const onAbort = () => settle(false);
862	      const settle = (approved: boolean) => {
863	        signal.removeEventListener("abort", onAbort);
864	        this.pendingApproval = undefined;
865	        resolve(approved);
866	      };
867	      signal.addEventListener("abort", onAbort, { once: true });
868	      this.pendingApproval = { id, tool, settle };
869	      this.emit({
870	        type: "approval.request",
871	        id,
872	        turn_id: turnId,
873	        tool,
874	        subject: toolSubject(args, tool),
875	        preview: redactedJson(args),
876	        review: approvalReview(tool, args, this.app.getConfig().workspace),
877	      });
878	    });
879	  }
