924	  private resolveCheckpointChoice(id: string, choice: CheckpointChoice): void {
925	    const pending = this.pendingCheckpointChoice;
926	    if (!pending || pending.id !== id) {
927	      this.emit({ type: "error", id, code: "NOT_FOUND", message: `No pending checkpoint choice with id ${id}.` });
928	      return;
929	    }
930	    if (!pending.choices.includes(choice)) {
931	      this.emit({ type: "error", id, code: "BAD_REQUEST", message: "That choice is not available for this checkpoint failure." });
932	      return;
933	    }
934	    pending.settle(choice);
935	  }
