937	  private slash(id: string, command: string, args: string): void {
938	    if (this.app.getAgent().getApprovalMode() === "read-only" && !readOnlySlashAllowed(command, args)) {
939	      this.emit({
940	        type: "slash.result",
941	        id,
942	        command: command.trim().replace(/^\//, "").toLowerCase(),
943	        success: false,
944	        output: "This command is disabled while the session is in read-only mode.",
945	      });
946	      return;
947	    }
948	    // /compact while work runs is queued, never refused or run concurrently: see queueCompaction.
949	    if (command.trim().replace(/^\//, "").toLowerCase() === "compact" && this.activeTurn && !this.shutdownPromise) {
950	      this.queueCompaction(id, args.split(/\s+/).includes("--llm"));
951	      return;
952	    }
953	    // Read-only diagnostics run beside a turn: they touch no conversation or workspace state the turn uses.
954	    if (this.activeTurn && !this.shutdownPromise && busySafe(command, args)) {
955	      void this.busySafeSlash(id, command, args);
956	      return;
957	    }
958	    if (this.rejectBusy(id)) return;
959	    this.runJob(id, findSlash(command), async (signal) => {
960	      const agent = this.app.getAgent();
961	      agent.setObserver(this.observerFor(id));
962	      let outcome: SlashOutcome;
963	      try {
964	        outcome = await routeSlash(this.slashHost(id), command, args, signal);
965	      } finally {
966	        agent.setObserver(undefined);
967	      }
968	      if (outcome.kind === "turn") {
969	        this.activeSpec = undefined;
970	        await this.gatedTurn(
971	          id,
972	          outcome.prompt,
973	          signal,
974	          {
975	            admitted: () => this.emit({ type: "slash.result", id, command: outcome.command, success: true, output: "", prompt: outcome.label }),
976	            refused: (message) => this.emit({ type: "error", id, code: "NO_PROVIDER", message }),
977	          },
978	          { title: outcome.title ?? outcome.label, checkpoint: outcome.checkpoint, step: outcome.step },
979	        );
980	        return;
981	      }
982	      if (outcome.command === "clear" && outcome.success) this.lastTurn = null;
983	      this.emit({
984	        type: "slash.result",
985	        id,
986	        command: outcome.command,
987	        success: outcome.success,
988	        // A diff keeps what the files say: control characters are made visible rather than removed.
989	        output: outcome.output,
990	        ...(outcome.format ? { format: outcome.format } : {}),
991	        ...(outcome.composer !== undefined ? { composer: outcome.composer } : {}),
992	        ...(outcome.clipboard !== undefined ? { clipboard: outcome.clipboard } : {}),
993	      });
994	    });
995	  }
