1157	  private resumeSession(id?: string): { ok: boolean; message: string } {
1158	    const manager = this.app.getSessionManager();
1159	    let session;
1160	    try {
1161	      session = !id || id === "latest" ? manager.getLatestSession() : manager.loadSession(id);
1162	    } catch (err: any) {
1163	      return { ok: false, message: err.message };
1164	    }
1165	    if (!session) return { ok: false, message: `Session not found: ${id || "latest"}` };
1166	    if (!Array.isArray(session.messages)) return { ok: false, message: `Session ${session.id} is unreadable: it has no message list.` };
1167	    if (session.workspace && fs.existsSync(session.workspace)) this.setWorkspace(session.workspace);
1168	    // The id changes together with the conversation, so a save after a partial restore never overwrites the previous session's record.
1169	    this.sessionId = session.id;
1170	    // What compaction replaced stays searchable after a resume (read_archive): only compactions this record committed.
1171	    const archiveNotice = this.app.getAgent().restoreConversation(session, (committed) => this.app.getSessionManager().readArchivedHistory(session.id, committed));
1172	    if (archiveNotice) this.emit({ type: "notice", text: archiveNotice });
1173	    if (Array.isArray(session.activePlan)) this.app.getAgent().setActivePlan(session.activePlan);
1174	    this.lastTurn = null;
1175	    this.emitHistory(session.id, withHarnessProvenance(session.messages), session.lastTurn);
1176	    // The count of the conversation is in the history header shown just before; this names the session.
1177	    return { ok: true, message: `Resumed session ${session.id}.` };
1178	  }
