1306	 * redaction, so a cut can never split a credential. Each limit is at least the cap the field's producer already
1307	 * applies, and a value the producer already cut with `capText` keeps its own `…[truncated N chars]` count (see
1308	 * limitEventFields), so this changes nothing that is sent today; it bounds the field if a producer stops capping. Event types not
1309	 * listed are structured or bounded elsewhere (paths: PATH_FIELDS; history: HISTORY_LIMITS); the coverage test in
1310	 * test/sidecar_projection.test.ts classifies every protocol event type.
1311	 */
1312	export const FIELD_LIMITS: Partial<Record<SidecarEvent["type"], Readonly<Record<string, number>>>> = {
1313	  "assistant.delta": { text: 64_000 },
1314	  "steer.ack": { message: MAX_TEXT_FIELD, text: 64_000 },
1315	  "file.diff": { path: 400, preview: 2 * DIFF_PREVIEW_CHARS, note: MAX_TEXT_FIELD },
1316	  activity: { tool: 200, subject: 200 },
1317	  "tool.start": { tool: 200, subject: MAX_TEXT_FIELD },
1318	  // summary: protocol toolSummary caps at MAX_SUMMARY; preview: TOOL_PREVIEW_LINES rows of at most 400 characters.
1319	  "tool.end": { tool: 200, summary: MAX_SUMMARY, preview: TOOL_PREVIEW_LINES * 401 },
1320	  "tool.detail": { tool: 200, subject: MAX_TEXT_FIELD, args: MAX_DETAIL, output: MAX_DETAIL, diff: MAX_DIFF_DETAIL },
1321	  "approval.request": { tool: 200, subject: MAX_TEXT_FIELD, preview: MAX_TEXT_FIELD },
1322	  "checkpoint.choice.request": { message: MAX_TEXT_FIELD },
1323	  "turn.result": { heading: MAX_TEXT_FIELD, line: MAX_TEXT_FIELD },
1324	  "slash.result": { output: MAX_SLASH_OUTPUT, prompt: MAX_TEXT_FIELD, composer: MAX_PASTE, clipboard: OSC52_MAX_BYTES },
1325	  notice: { text: MAX_TEXT_FIELD, detail: MAX_TEXT_FIELD },
1326	  error: { message: MAX_TEXT_FIELD },
1327	  "provider.auth": { instructions: MAX_TEXT_FIELD },
1328	  "provider.result": { message: MAX_TEXT_FIELD },
1329	  "model.result": { message: MAX_TEXT_FIELD },
