1336	const HISTORY_LIMITS = { toolName: 80, toolSubject: 200, text: HISTORY_CHARS } as const;
1337	
1338	/** Longest `…[truncated N chars]` marker capText appends after the kept text. */
1339	const CAP_MARKER_ROOM = 40;
1340	const CAP_MARKER = /…\[truncated \d+ chars\]$/;
1341	
1342	function limitEventFields(event: any): void {
1343	  for (const [field, max] of Object.entries(FIELD_LIMITS[event.type as SidecarEvent["type"]] ?? {})) {
1344	    const value = event[field];
1345	    if (typeof value !== "string") continue;
1346	    // Already cut to this limit by its producer: keep the producer's count of what was dropped. A model- or tool-supplied
1347	    // text that fakes the marker only spoofs that count; the skip is bounded, since the value is at most max + CAP_MARKER_ROOM.
1348	    if (value.length <= max + CAP_MARKER_ROOM && CAP_MARKER.test(value)) continue;
1349	    event[field] = capText(value, max);
1350	  }
1351	  if (event.type === "history") {
1352	    for (const entry of event.messages as HistoryEntry[]) {
1353	      if (entry.role === "outcome") continue;
1354	      if (entry.role === "tool") {
1355	        if (typeof entry.tool === "string") entry.tool = capText(entry.tool, HISTORY_LIMITS.toolName);
1356	        entry.text = capText(entry.text, HISTORY_LIMITS.toolSubject);
1357	      } else {
1358	        entry.text = capText(entry.text, HISTORY_LIMITS.text);
1359	      }
1360	    }
1361	  }
1362	}
