1374	/**
1375	 * The single sanitizing stage for protocol events. call sites hand over full, raw text; this redacts it once (the
1376	 * canonical classifier over the whole structure, so keys and nested projected records are covered, plus the literal
1377	 * patterns and terminal-control handling), treats path fields component-wise so generated directory names are not
1378	 * mistaken for credentials, and only then cuts each field to its limit. Fails closed: if classification throws the
1379	 * event is dropped, never serialized half-sanitized.
1380	 */
1381	export function formatSafeSidecarEvent(event: SidecarEvent): SidecarEvent | undefined {
1382	  try {
1383	    const staged: any = { ...event };
1384	    const paths: Record<string, string> = {};
1385	    for (const field of PATH_FIELDS[event.type] ?? []) {
1386	      if (typeof staged[field] !== "string") continue;
1387	      paths[field] = visibleControls(redactSecretPatterns(redactPathForOutput(staged[field])));
1388	      staged[field] = "[NEXUS_PATH]";
1389	    }
1390	    const safe: any = finishStrings(redactForPersistence(staged));
1391	    Object.assign(safe, paths);
1392	    limitEventFields(safe);
1393	    return safe as SidecarEvent;
1394	  } catch {
1395	    return undefined;
1396	  }
1397	}
