1422	 * other stdout write (agent banners, spinners, console.log) is dropped, or sent to stderr with NEXUS_DEBUG=1.
1423	 */
1424	async function main(argv: string[]): Promise<void> {
1425	  const protocolWrite = process.stdout.write.bind(process.stdout);
1426	  const debug = process.env.NEXUS_DEBUG === "1";
1427	  const toStderr = (...args: unknown[]): void => {
1428	    if (debug) process.stderr.write(`${formatSafeSidecarDiagnostic(args)}\n`);
1429	  };
1430	
1431	  const program = new Command()
1432	    .allowExcessArguments(true) // as the nexus CLI: commander 13+ would otherwise reject extra arguments the sidecar always ignored
1433	    .name("nexus-sidecar")
1434	    .option("-e, --endpoint <url>", "Local LLM endpoint")
1435	    .option("-m, --model <name>", "Model name")
1436	    .option("-w, --workspace <path>", "Workspace directory")
1437	    .option("-s, --max-steps <number>", "Steps per segment (continuation checkpoints there instead of stopping)")
1438	    .option("--max-total-steps <number>", "Continuation: an explicit total-step limit for one turn (default: none; progressing work continues)")
1439	    .option("--strict-token-count", "Refuse a request the connection could not count on a worker (default: proceed on the labelled estimate)")
1440	    .option("--max-turn-minutes <number>", "Continuation: an explicit wall-clock limit for one turn in minutes (default: none)")
1441	    .option("--stagnation-steps <number>", "Continuation: stop after this many steps without progress (default 12)")
1442	    .option("--no-continuation", "End a turn at --max-steps instead of continuing while it makes progress")
1443	    .option("-t, --temperature <number>", "Model temperature")
1444	    .option("--shell <type>", "Shell for commands", "bash")
1445	    .option("--fallback <urls>", "Comma-separated fallback LLM endpoints")
1446	    .option("--context-limit <tokens>", "Model context window limit in tokens")
1447	    .option("--dry-run", "Simulate file modifications without writing changes to disk")
1448	    .option("--read-only", "Reject all mutating tool executions and commands")
1449	    .option("--sandbox [mode]", "Isolate command execution using bubblewrap or Docker")
1450	    .option("--sandbox-network", "With --sandbox: let sandboxed commands and the sandboxed native worker use the network (off by default)")
1451	    .option("--worktree", "Isolate execution inside an ephemeral git worktree")
1452	    .option("--worktree-branch <name>", "Run inside the named git worktree for this branch (created if missing); kept after the run, merge it with `nexus worktree merge`")
1453	    .option("--authoritative-verifier <command>", "Trusted command that must pass before any task completion; its success may authorize automatic worktree merge")
1454	    .option("--deliverable-file <path>", "Operator-declared workspace-relative product file used for VERIFIED binding (repeatable)", (value: string, previous: string[] = []) => [...previous, value], [])
1455	    .option("--record-flight", "Record execution into an append-only .flightlog")
1456	    .option("--planner-model <name>", "Deep reasoning model for planning")
1457	    .option("--planner-endpoint <url>", "Inference endpoint for the planner model")
1458	    .option("--coder-model <name>", "Model for code implementation")
1459	    .option("--coder-endpoint <url>", "Inference endpoint for the coder model")
1460	    .option("--approve", "Require operator approval before edits and shell commands")
1461	    .option("-y, --yes", "Run non-interactively without approval prompts (forces auto mode)")
1462	    .option("--mode <mode>", "Execution mode: auto, review, or read-only (default: review; folder trust does not change it)")
1463	    .option("-r, --resume [id]", "Resume a saved session (the latest when no id is given)")
1464	    .parse(argv);
1465	
1466	  // Commander help is ordinary CLI output, before protocol-only stdout
1467	  // handling begins. Parsing help and metadata invocations is read-only: do
1468	  // it before restore recovery, then hold a lifetime lease before any normal
