1470	  // point directly, without passing through index.ts.
1471	  (process.stdout as any).write = (chunk: unknown, encoding?: unknown, cb?: unknown): boolean => {
1472	    if (debug && (typeof chunk === "string" || chunk instanceof Uint8Array)) {
1473	      process.stderr.write(formatSafeSidecarStdoutSummary(chunk));
1474	    }
1475	    const done = typeof encoding === "function" ? encoding : cb;
1476	    if (typeof done === "function") (done as () => void)();
1477	    return true;
1478	  };
1479	  console.log = toStderr;
1480	  console.info = toStderr;
1481	  console.warn = toStderr;
1482	  console.debug = toStderr;
1483	  console.error = (...args: unknown[]) => process.stderr.write(`${formatSafeSidecarDiagnostic(args)}\n`);
1484	  const home = process.env.HOME || os.homedir();
1485	  const { acquireClientLease, releaseClientLease } = await import("./core/client_lease.js");
1486	  const { hasPendingStateRestore, recoverPendingStateRestore } = await import("./core/state_restore.js");
1487	  if (hasPendingStateRestore(home) && !recoverPendingStateRestore(home)) {
1488	    throw new Error("Pending state restore could not be recovered; no state was admitted");
1489	  }
1490	  const lease = acquireClientLease(home);
1491	  process.once("exit", () => releaseClientLease(lease));
1492	  loadEnvironment();
1493	  const configLoadError = operatorConfigLoadError();
1494	  if (configLoadError) throw new Error(`Configuration error: ${configLoadError.message}`);
1495	  const options = program.opts();
1496	  const config = await autoDetectModel(buildConfig(options), { resuming: Boolean(options.resume) });
1497	  config.surface = "tui";
1498	  const app = new ApplicationCore(config);
1499	  const server = new SidecarServer({
1500	    app,
1501	    mode: config.approvalMode,
1502	    resume: typeof options.resume === "string" ? options.resume : options.resume ? "latest" : undefined,
1503	    write: (line) => {
1504	      protocolWrite(line);
1505	    },
