1508	
1509	  const report = (err: unknown) => process.stderr.write(`nexus sidecar: ${formatSafeSidecarDiagnostic([err])}\n`);
1510	  const input = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });
1511	  input.on("line", (line) => {
1512	    server.handleLine(line).catch(report);
1513	  });
1514	  const requestShutdown = () => {
1515	    server.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })).catch(report);
1516	  };
1517	  input.on("close", requestShutdown);
1518	  process.stdout.on("error", requestShutdown);
1519	  server.start();
