1532	if (isEntryPoint(process.argv[1], import.meta.url)) {
1533	  main(process.argv).catch((err) => {
1534	    const message = err instanceof Error ? err.message : String(err);
1535	    process.stderr.write(`nexus sidecar failed to start: ${formatSafeSidecarText(message)}\n`);
