848	  private requestApproval(turnId: string, signal: AbortSignal, tool: string, args: Record<string, any>): Promise<boolean> {
849	    if (this.alwaysApprove && tool !== DELIBERATE_APPROVAL) return Promise.resolve(true);
850	    const queued = this.approvalTail.then(() => this.openApproval(turnId, signal, tool, args));
851	    this.approvalTail = queued.catch(() => {});
852	    return queued;
