1113	  /** Same record the REPL saves after each turn. Skipped (false) while the conversation holds only the system prompt; true once written. */
1114	  private saveSession(title?: string, turn?: TurnResult): boolean {
1115	    const agent = this.app.getAgent();
1116	    const messages = agent.getMessages();
1117	    if (messages.length <= 1) return false;
1118	    const config = this.app.getConfig();
1119	    const now = new Date().toISOString();
1120	    const manager = this.app.getSessionManager();
1121	    // Originals compaction replaced are archived beside the session by the agent's archive sink before this record
1122	    // (which names the committed compactions in `history`) is written.
1123	    const receipt = this.app.getActiveValidationReceipt();
1124	    const lastTurn = turn ?? agent.getLastTurnResult();
1125	    // The recovery fields live in the agent's durable checkpoint; the session record replaces the whole task record.
1126	    const durableState = this.app.getTaskState();
1127	    manager.saveSession(
1128	      {
1129	        id: this.sessionId,
1130	        title: title ? title.slice(0, 60).replace(/\n/g, " ") : "Active Session",
1131	        createdAt: now,
1132	        updatedAt: now,
1133	        workspace: config.workspace,
1134	        model: config.model,
1135	        endpoint: persistableEndpoint(config.endpoint),
1136	        messages,
1137	        unverifiedChangesPending: agent.hasUnverifiedChanges(),
1138	        tokenStats: agent.getTokenStats(),
1139	        // The authoritative task state, not only the conversation: plan, milestones, receipts, objective and history.
1140	        activePlan: agent.getActivePlan(),
1141	        milestones: agentMilestones(agent),
1142	        validationReceipts: receipt ? [receipt] : [],
1143	        objective: agent.getObjective() ?? null,
1144	        findings: agent.getFindings(),
1145	        history: agent.getHistoryCompleteness(),
1146	        providerRecovery: durableState.providerRecovery,
1147	        operation: durableState.operation,
1148	        changeBaseline: durableState.changeBaseline,
1149	        ...(turn ? { status: lifecycleStatusForTurn(turn) } : {}),
1150	        ...(lastTurn ? { lastTurn } : {}),
1151	      },
1152	      agent.getWorkspacePathIdentity(),
