1180	  /**
1181	   * The resumed conversation for the client to show, in order: operator prompts, steering, the agent's replies, the
1182	   * tools it called (name and subject; results stay in the session record), and the last turn's outcome. Nexus's own
1183	   * prompts (continuation, recovery) and the runtime context appended to prompts are left out; text is redacted and
1184	   * bounded, and only the latest HISTORY_ENTRIES entries are sent.
1185	   */
1186	  private emitHistory(sessionId: string, messages: ChatMessage[], lastTurn?: TurnResult | null): void {
1187	    const text = (m: ChatMessage) => (typeof m.content === "string" ? m.content : Array.isArray(m.content) ? m.content.map((p: any) => (typeof p?.text === "string" ? p.text : "")).join("") : "");
1188	    const entries: HistoryEntry[] = [];
1189	    for (const m of messages) {
1190	      const body = text(m);
1191	      if (m.role === "user") {
1192	        if (!body.trim() || isHarnessNote(m)) continue;
1193	        // Steering is stored as "[Operator steering <id>]: text": shown as steering, without the marker.
1194	        const typed = body.replace(/(\n+\[(?:Git Status|Active Plan): [^\n]*\])+\s*$/, "");
1195	        if (typed.startsWith(STEERING_PREFIX)) entries.push({ role: "steering", text: typed.slice(typed.indexOf("]:") + 2).trim() });
1196	        else entries.push({ role: "user", text: typed });
1197	      } else if (m.role === "assistant") {
1198	        if (body.trim()) entries.push({ role: "assistant", text: body });
1199	        for (const call of m.tool_calls ?? []) {
1200	          let args: Record<string, any> = {};
1201	          try {
1202	            args = JSON.parse(call.function.arguments || "{}");
1203	          } catch {}
1204	          entries.push({ role: "tool", tool: call.function.name, text: toolSubject(args, call.function.name) });
1205	        }
1206	      }
1207	    }
1208	    if (lastTurn) {
1209	      const { heading, line } = summarizeTurn(lastTurn);
1210	      entries.push({ role: "outcome", heading: heading, text: line, turn: projectTurn(lastTurn) });
1211	    }
1212	    const conversation = entries.filter((e) => e.role !== "tool" && e.role !== "outcome").length;
1213	    this.emit({ type: "history", session: sessionId, total: conversation, messages: entries.slice(-HISTORY_ENTRIES) });
1214	  }
