1216	  private shutdown(): Promise<void> {
1217	    for (const signIn of this.signIns.values()) signIn.cancel();
1218	    this.signIns.clear();
1219	    for (const list of this.modelLists.values()) list.abort();
1220	    this.shutdownPromise ??= (async () => {
1221	      this.startupProbeAbort.abort();
1222	      this.turnAbort?.abort(new Error("sidecar shutdown"));
1223	      await this.idle();
1224	      this.app.shutdown();
1225	      this.onShutdown();
1226	    })();
1227	    return this.shutdownPromise;
1228	  }
